create or replace function public.cineo_reorder_chapters(actor uuid,sid bigint,season_number integer,ids bigint[]) returns void language plpgsql security invoker set search_path='' as $$declare s public.cineo_shows;n integer:=1;eid bigint;expected integer;temporary_season integer;begin select * into s from public.cineo_shows where id=sid for update;if s.owner_id is distinct from actor or s.status not in ('draft','rejected') then raise exception 'Reordene capítulos somente em uma produção em rascunho';end if;select count(*) into expected from public.cineo_episodes where show_id=sid and season=season_number;if expected<>cardinality(ids) or expected<>(select count(distinct x) from unnest(ids)x) or exists(select 1 from unnest(ids)x where not exists(select 1 from public.cineo_episodes where id=x and show_id=sid and season=season_number)) then raise exception 'Lista de capítulos inválida';end if;
 -- Move through an unused, valid season to preserve immediate uniqueness and chapter bounds.
 select gs.value into temporary_season from generate_series(1,1000) as gs(value) where not exists(select 1 from public.cineo_episodes where show_id=sid and season=gs.value) limit 1;if temporary_season is null then raise exception 'Nenhuma temporada temporária disponível';end if;
 update public.cineo_episodes set season=temporary_season where show_id=sid and season=season_number;
 foreach eid in array ids loop update public.cineo_episodes set season=season_number,episode_number=n where id=eid;n:=n+1;end loop;
end$$;
